def max_product(arr):
    if not arr:
        return 0

    # Initialize the products with the first element
    increasing_products = arr.copy()

    # Iterate through the array starting from the second element
    for i in range(1, len(arr)):
        for j in range(i):
            # If the subsequence is increasing, update the product
            if arr[i] > arr[j]:
                increasing_products[i] = max(increasing_products[i], increasing_products[j] * arr[i])

    # Return the maximum product found
    return max(increasing_products)

